beginning.embedded_functions:
#include <sys/time.h>

#define OCPP_HB_SLOTS 4096
#define OCPP_HB_PROBES 8

struct ocpp_hb_slot {
	uint32_t ip;
	uint16_t port;
	uint8_t  used;
	uint8_t  reported;
	uint32_t count;
	time_t   window_start;
	time_t   last_seen;
};

/* one table per thread: mmt-probe hands all packets of a flow to the same thread */
static __thread struct ocpp_hb_slot ocpp_hb_table[OCPP_HB_SLOTS];
static uint32_t ocpp_hb_limit    = 10;
static time_t   ocpp_hb_window_s = 10;

static void on_load(){
	const char *str = getenv("MMT_SEC_OCPP_HEARTBEAT_LIMIT");
	if( str != NULL && atoi( str ) > 0 )
		ocpp_hb_limit = atoi( str );
	str = getenv("MMT_SEC_OCPP_HEARTBEAT_WINDOW_S");
	if( str != NULL && atoi( str ) > 0 )
		ocpp_hb_window_s = atoi( str );
}

static void on_unload(){
}

/* Returns 1 once per window, on the Heartbeat that makes the session exceed the limit. */
static inline int em_ocpp_heartbeat_flood( const char *ip_src, double src_port, const void *utime ){
	uint32_t ip, h, i;
	uint16_t port = (uint16_t) src_port;
	time_t now;
	struct ocpp_hb_slot *s = NULL, *oldest = NULL;

	if( ip_src == NULL || utime == NULL )
		return 0;
	memcpy( &ip, ip_src, sizeof( ip ) );
	now = ((const struct timeval *) utime)->tv_sec;

	h = (ip * 2654435761u) ^ (port * 40503u);
	for( i = 0; i < OCPP_HB_PROBES; i++ ){
		struct ocpp_hb_slot *c = &ocpp_hb_table[ (h + i) % OCPP_HB_SLOTS ];
		if( c->used && c->ip == ip && c->port == port ){
			s = c;
			break;
		}
		if( oldest == NULL || !c->used || (oldest->used && c->last_seen < oldest->last_seen) )
			oldest = c;
	}
	if( s == NULL ){
		/* new session, or a session evicted earlier: take a free or the least recent slot */
		s = oldest;
		s->used = 1;
		s->ip = ip;
		s->port = port;
		s->count = 0;
		s->reported = 0;
		s->window_start = now;
	}
	s->last_seen = now;
	if( now - s->window_start >= ocpp_hb_window_s ){
		s->window_start = now;
		s->count = 0;
		s->reported = 0;
	}
	s->count ++;
	if( s->count > ocpp_hb_limit && !s->reported ){
		s->reported = 1;
		return 1;
	}
	return 0;
}
